import {arenaName} from './arenas.js';
export function setupFriendsUI({getClient,create,join,context=()=>({})},root=document){
 const $=id=>root.getElementById(id);let notice='',results=[],busy=false,lastView='';
 const button=(label,callback)=>{const b=root.createElement('button');b.type='button';b.className='secondary';b.textContent=label;b.addEventListener('click',async()=>{if(busy)return;busy=true;try{await callback();}catch(error){notice=error.message;}finally{busy=false;render(true);}});return b;};
 function row(container,label,detail,actions=[]){const line=root.createElement('div'),name=root.createElement('strong'),small=root.createElement('small'),info=root.createElement('div'),controls=root.createElement('div');line.className='friend-row';controls.className='friend-actions';name.textContent=label;small.textContent=detail;info.append(name,small);for(const b of actions)b.dataset.focusKey=label+'|'+(detail.match(/BC-[A-F0-9]{12}/)?.[0]||detail)+'|'+b.textContent;controls.append(...actions);line.append(info,controls);container.append(line);}
 const status=p=>(p.online?(p.status==='playing'?'IN GAME':p.status==='lobby'?'IN LOBBY':p.status==='away'?'AWAY':'ONLINE'):'OFFLINE')+' · '+p.id;
 async function act(op,peer){const c=getClient();if(!c)return;const result=await c.action(op,{peer});if(result)notice=op==='request'?'Friend request sent.':op==='accept'?'Friend added.':'Updated.';}
 async function enter(id){if(context().status==='playing'){notice='Leave your current match before joining another lobby.';return;}const c=getClient(),value=await c?.join(id);if(value?.code){$('friends-dialog').close();join(value.code,c.url);}}
 function render(force=false){
  const c=getClient(),s=c?.state;const counter=$('online-player-count');counter.textContent=s&&!c.error?String(s.online):'—';$('online-presence').title=c?.error||'Players seen on this game server in the last minute; tabs and bots are excluded.';
  $('friends-notification').textContent=s&&s.incoming.length+s.invites.length?' ('+(s.incoming.length+s.invites.length)+')':'';
  if(!$('friends-dialog').open&&!force)return;const signature=JSON.stringify([s,c?.error,notice,results,context().room?.code,context().room?.connected,context().room?.canManage]);if(!force&&signature===lastView)return;lastView=signature;const focusKey=root.activeElement?.dataset?.focusKey;
  $('my-player-id').value=s?.self.id||'CONNECTING…';$('friends-status').textContent=c?.error||notice||(c?.persistent===false?'Local saving is blocked. This player ID lasts for this visit only.':!c?'Friends need the secure game server.':!s?'Connecting to the player directory…':'Search by display name or exact ID. Requests need acceptance.');
  $('my-player-id').title=c?.persistent===false?'This browser blocked local saving. This ID lasts for this visit only.':'Saved on this browser profile.';
  $('friends-search-button').disabled=!s;$('new-social-lobby').disabled=context().status==='playing';const own=context().room;const canHost=!!(own?.dedicated&&own.canManage&&own.connected);$('share-lobby').disabled=!canHost;$('unshare-lobby').disabled=!s?.ownLobby;$('lobby-share-hint').textContent=canHost?'You are the host. Share your lobby or invite a friend below.':'Create a dedicated lobby to share it or send invites.';
  const pending=$('friend-requests');pending.replaceChildren();for(const p of s?.incoming||[])row(pending,p.name,status(p),[button('ACCEPT',()=>act('accept',p.id)),button('DECLINE',()=>act('decline',p.id)),button('BLOCK',()=>act('block',p.id))]);
  for(const p of s?.outgoing||[])row(pending,p.name,'REQUEST SENT · '+p.id,[button('CANCEL',()=>act('decline',p.id))]);if(!pending.children.length)pending.textContent='No pending requests.';
  const list=$('friends-list');list.replaceChildren();for(const p of [...(s?.friends||[])].sort((a,b)=>Number(b.online)-Number(a.online)||a.name.localeCompare(b.name))){const invite=button('INVITE',async()=>{const result=await c.invite(p.id,$('lobby-visibility').value);if(result)notice='Lobby invite sent.';});invite.disabled=!canHost;row(list,p.name,status(p),[invite,button('REMOVE',()=>act('remove',p.id)),button('BLOCK',()=>act('block',p.id))]);}if(!list.children.length)list.textContent='Add friends to see their online status and invite them.';
  const found=$('friend-search-results');found.replaceChildren();for(const p of results){const known=s?.friends.some(q=>q.id===p.id),pending=s?.outgoing.some(q=>q.id===p.id);const add=button(known?'FRIENDS':pending?'REQUEST SENT':'ADD FRIEND',()=>act('request',p.id));add.disabled=known||pending;row(found,p.name,status(p),[add]);}
  const invites=$('lobby-invites');invites.replaceChildren();for(const i of s?.invites||[])row(invites,i.from.name,arenaName(i.lobby.arena)+' · LOBBY INVITE',[button('JOIN',()=>enter(i.lobby.id)),button('DISMISS',()=>c.action('dismiss',{invite:i.id}))]);if(!invites.children.length)invites.textContent='No lobby invites.';
  const lobbies=$('lobby-directory');lobbies.replaceChildren();for(const l of s?.lobbies||[]){const b=button(l.id===s.self.id?'OPEN LOBBY':l.playing?'JOIN / SPECTATE':'JOIN',()=>l.id===s.self.id?create(true):enter(l.id));b.disabled=l.id!==s.self.id&&l.people>=l.maxPeople;row(lobbies,l.name+'’s lobby',`${arenaName(l.arena)} · ${l.people}/${l.maxPeople} · ${l.visibility.toUpperCase()}`, [b]);}if(!lobbies.children.length)lobbies.textContent='No shared lobbies. Create one or ask a friend for an invite.';
  const blocked=$('blocked-players');blocked.replaceChildren();for(const p of s?.blocked||[])row(blocked,p.name,p.id,[button('UNBLOCK',()=>act('unblock',p.id))]);
  if(focusKey)[...$('friends-dialog').querySelectorAll('[data-focus-key]')].find(node=>node.dataset.focusKey===focusKey)?.focus({preventScroll:true});
 }
 function open(){if(!$('friends-dialog').open)$('friends-dialog').showModal();render(true);getClient()?.sync();}
 for(const id of ['friends-button','party-friends-button','pause-friends-button'])$(id).addEventListener('click',open);
 $('friends-search-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;try{const value=await getClient()?.action('search',{query:$('friend-search').value});results=value?.results||[];notice=results.length?'Choose the matching name and player ID.':'No players found.';}finally{busy=false;render(true);}});
 $('copy-player-id').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('my-player-id').value);notice='Player ID copied.';}catch{$('my-player-id').select();notice='Copy the selected player ID.';}render(true);});
 $('friends-refresh').addEventListener('click',()=>getClient()?.sync());$('new-social-lobby').addEventListener('click',()=>{ $('friends-dialog').close();create(false);});
 $('share-lobby').addEventListener('click',async()=>{try{await getClient()?.share($('lobby-visibility').value);notice='Lobby shared · '+$('lobby-visibility').selectedOptions[0].textContent;}catch(error){notice=error.message;}render(true);});
 $('unshare-lobby').addEventListener('click',()=>getClient()?.action('unpublish'));
 return {render,open};
}
